-- Chat v2 part 1: message columns + receipts + reactions
 alter table public.messages add column if not exists reply_to_message_id uuid references public.messages(id) on delete set null;
 alter table public.messages add column if not exists is_edited boolean not null default false;
 alter table public.messages add column if not exists edited_at timestamptz;
 alter table public.messages add column if not exists deleted_at timestamptz;
 alter table public.messages add column if not exists deleted_for_all boolean not null default false;
 alter table public.messages add column if not exists deleted_for uuid[] not null default '{}';
 create index if not exists messages_reply_idx on public.messages (reply_to_message_id);
 create index if not exists messages_conversation_created_idx on public.messages (conversation_id, created_at asc);
 create table if not exists public.message_receipts (message_id uuid not null references public.messages(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, delivered_at timestamptz, seen_at timestamptz, created_at timestamptz not null default now(), primary key (message_id, user_id));
 create index if not exists message_receipts_user_idx on public.message_receipts (user_id, seen_at);
 alter table public.message_receipts enable row level security;
 drop policy if exists message_receipts_select on public.message_receipts;
 create policy message_receipts_select on public.message_receipts for select to authenticated using (exists (select 1 from public.messages m where m.id = message_id and public.is_conversation_member(m.conversation_id)));
 drop policy if exists message_receipts_upsert_own on public.message_receipts;
 create policy message_receipts_upsert_own on public.message_receipts for insert to authenticated with check (user_id = auth.uid());
 drop policy if exists message_receipts_update_own on public.message_receipts;
 create policy message_receipts_update_own on public.message_receipts for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
 revoke all on public.message_receipts from anon, authenticated;
 grant select, insert, update on public.message_receipts to authenticated;
 create table if not exists public.message_reactions (message_id uuid not null references public.messages(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, emoji text not null check (emoji in ('❤️','👍','😂','😮','😢','🙏')), created_at timestamptz not null default now(), primary key (message_id, user_id));
 create index if not exists message_reactions_message_idx on public.message_reactions (message_id);
 alter table public.message_reactions enable row level security;
 drop policy if exists message_reactions_select on public.message_reactions;
 create policy message_reactions_select on public.message_reactions for select to authenticated using (exists (select 1 from public.messages m where m.id = message_id and public.is_conversation_member(m.conversation_id)));
 drop policy if exists message_reactions_write_own on public.message_reactions;
 create policy message_reactions_write_own on public.message_reactions for insert to authenticated with check (user_id = auth.uid());
 drop policy if exists message_reactions_delete_own on public.message_reactions;
 create policy message_reactions_delete_own on public.message_reactions for delete to authenticated using (user_id = auth.uid());
 drop policy if exists message_reactions_update_own on public.message_reactions;
 create policy message_reactions_update_own on public.message_reactions for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
 revoke all on public.message_reactions from anon, authenticated;
 grant select, insert, update, delete on public.message_reactions to authenticated;
 drop policy if exists messages_update_own on public.messages;
 create policy messages_update_own on public.messages for update to authenticated using (sender_id = auth.uid()) with check (sender_id = auth.uid());
 grant update on public.messages to authenticated;
 alter table public.notifications add column if not exists conversation_id uuid references public.conversations(id) on delete cascade;
 alter table public.notifications add column if not exists message_id uuid references public.messages(id) on delete cascade;
 alter table public.notifications drop constraint if exists notifications_type_check;
 do $$ begin alter table public.notifications add constraint notifications_type_check check (type in ('post_like','post_comment','post_fire','post_insight','post_same','post_talk','comment_reaction','comment_talk','connection_request','connection_accepted','group_invite','group_invite_accepted','group_invite_declined','group_member_removed','group_ownership_transferred','chat_message')); exception when duplicate_object then null; end $$;
 create index if not exists notifications_chat_idx on public.notifications (recipient_id, created_at desc);
